	if len(assigneeIDs) > 0 {
		for _, assignee := range assignees {
			notify_service.IssueChangeAssignee(ctx, issue.Poster, issue, assignee, false, assigneeCommentMap[assignee.ID])
		}
	}

	return nil
}

